-- =====================================================================
-- khaustan_menu_data_SaharaHotel_400070002_KhaustanRestaurantMenu.sql
--
-- RESTAURANT : Sahara Hotel  ("No Branch")
--              Near Kalpana Cinema, L.B.S Marg, Kurla (W.), Mumbai - 400 070
-- IDS        : establishment_id = restaurant_id = source_id = 400070002
-- BATCH      : extraction_batch_id 400070002001, source file Sahara_Hotel_Menu.docx
-- TARGET     : PostgreSQL, database "KhaustanRestaurantMenu" (one transaction)
-- SCHEMA REF : khaustan-KhaustanRestaurantMenu-Create_DB-postgresql.sql
-- LOOKUP REF : khaustan_lookup_data_seed_KhaustanRestaurantMenu.sql
--
-- HOW TO RUN  psql -v ON_ERROR_STOP=1 -f <this file>
--             Run it once in a disposable/staging database first. It could not be
--             executed against PostgreSQL where it was produced.
--
-- THIS SCRIPT INSERTS NO LOOKUP DATA. It only READS service_mode, delivery_provider,
-- protein_type and platform_tag rows (by code, never by numeric id). The PRE-FLIGHT
-- block below aborts before writing anything if a needed lookup row is missing.
--
-- ROWS LOADED
--   establishment 1 | restaurant 1 | restaurant_phone 5 | restaurant_service_mode 2
--   restaurant_delivery 1 | restaurant_delivery_provider 2 | source_record 1
--   menu_extraction_batch 1 | menu_board 1 | menu_category 38 | menu_board_category 38
--   canonical_dish up to 492 (+ names; a dish that already exists is skipped) | menu_item 498 | menu_item_source 498
--   menu_item_variant 551 | menu_item_price 551 | menu_item_price_source 551
--   menu_item_tag 65 | menu_item_availability 10 | menu_board_item 498
--
-- CONVENTIONS / DECISIONS
--  1. IDs are explicit literals. Fixed by instruction: establishment/restaurant/source
--     400070002; menu_category, menu_item, menu_item_source, menu_item_variant,
--     menu_item_price, menu_item_availability, menu_board_item start at 400070002001.
--     menu_board_category has no id column (PK = board + category). Tables the
--     instructions did not cover use the same 400070002001+ range: canonical_dish,
--     canonical_dish_name, restaurant_phone, restaurant_delivery_provider,
--     menu_board, menu_extraction_batch.
--  2. Names are stored exactly as printed (UPPER CASE); normalized_name = lower-case with
--     collapsed spaces; nothing is expanded or corrected. Only sibling rows that are sizes of
--     one dish were merged into menu_item_variant rows: (FULL)/(HALF) x6 dishes,
--     (4..7 PERSON) x2 thaals, ALL SOFTDRINKS sizes x1. Table column headers
--     (Half/Full, Khubus/Rumali, SCOOP/500 gram TUB) are variants too. Everything
--     else keeps its printed text, e.g. "(6 PCS)", "(BONELESS)", "(NEW)", "(SUNDAY)".
--  3. Categories: 38 menu_category rows were created (instruction). The 11 pt
--     sub-headings are child categories of the preceding 14 pt heading: VEG. (of CHINESE
--     STARTERS), RICE WITH GRAVY (of FRIED RICE), SALAD & PLATER SHAWARMA (of SHAWARMA),
--     SEASONAL ICE-CREAM (of SCOOP ICE-CREAM). menu_item.raw_category_text keeps the
--     verbatim heading. One a_la_carte board holds every category and item.
--  4. Prices: the menu says "This Menu Rate Effect from 1st January 2026." so every price
--     has effective_from 2026-01-01 and the board has valid_from 2026-01-01. Currency INR
--     (default). GST/taxes are not mentioned on the menu -> tax_* columns left NULL.
--  5. "[Spicy]" and "[Green Gravy]" are printed as text tokens with a legend at the foot of
--     the menu -> removed from the name and stored as menu_item_tag SPICY / GREEN_GRAVY.
--     The 9 items of the CHEF SPECIAL section also get CHEFS_SPECIAL.
--  6. The menu prints no veg/non-veg symbols. food_classification_code is derived from
--     the printed name/section (chicken/mutton/fish/prawns/egg words, VEG./PANEER/DAL...,
--     breads, rice, juices, shakes, kulfi...). It is NULL for the 14 items where
--     ingredients are not evident (see review block 2). is_jain / is_vegan / is_eggless are
--     NULL everywhere; spice_level is NULL (the symbol carries no level).
--  7. Day-named specials ("(SUNDAY)" ... "(SATURDAY)", "MUTTON KHICHDI (FRIDAY)") also get
--     menu_item_availability rows (day_of_week 1 = Monday, no times printed).
--  8. Schema check: ck_menu_item_price_amount in the supplied schema already uses
--     "= TRUE / = FALSE", so the 4 "(SL. RATE)" market-price rows (3 dishes) insert cleanly (the
--     boolean = integer problem seen in an earlier schema version is not present).
--  9. Not loaded: opening hours (closing time not printed), one price with no dish name,
--     and restaurant-level notes with no column -- see the trailing review blocks.
-- =====================================================================

--\connect "KhaustanRestaurantMenu"
\set ON_ERROR_STOP on

BEGIN;

-- ---------------------------------------------------------------------
-- 0. PRE-FLIGHT (reads only; raises before anything is written)
-- ---------------------------------------------------------------------
DO $pre$
DECLARE
    v_missing text;
BEGIN
    SELECT string_agg(m.item, ', ' ORDER BY m.item)
      INTO v_missing
      FROM (
            SELECT 'service_mode.' || t.code AS item
              FROM (VALUES ('delivery'), ('bulk_catering')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM service_mode s WHERE s.code = t.code)
            UNION ALL
            SELECT 'delivery_provider.' || t.code
              FROM (VALUES ('SWIGGY'), ('ZOMATO')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM delivery_provider d WHERE d.provider_code = t.code)
            UNION ALL
            SELECT 'protein_type.' || t.code
              FROM (VALUES ('CHICKEN'), ('MUTTON'), ('SEAFOOD'), ('EGG')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM protein_type p WHERE p.code = t.code)
            UNION ALL
            SELECT 'platform_tag.' || t.code
              FROM (VALUES ('SPICY'), ('GREEN_GRAVY'), ('CHEFS_SPECIAL')) AS t(code)
             WHERE NOT EXISTS (SELECT 1 FROM platform_tag g WHERE g.tag_code = t.code)
           ) AS m;

    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'Sahara Hotel load aborted - lookup rows missing: %. Run the lookup seed script first.', v_missing;
    END IF;

    IF EXISTS (SELECT 1 FROM menu_item WHERE restaurant_id = 400070002)
       OR EXISTS (SELECT 1 FROM menu_extraction_batch WHERE restaurant_id = 400070002)
       OR EXISTS (SELECT 1 FROM source_record WHERE source_id = 400070002) THEN
        RAISE EXCEPTION 'Sahara Hotel (restaurant_id 400070002) already has menu data or source_id 400070002 is in use - refusing to load twice.';
    END IF;

    IF EXISTS (SELECT 1 FROM establishment
                WHERE normalized_name = 'sahara hotel' AND postal_code = '400070'
                  AND establishment_id <> 400070002) THEN
        RAISE EXCEPTION 'An establishment named sahara hotel already exists in 400070 under a different id - resolve before loading.';
    END IF;
END
$pre$;

-- ---------------------------------------------------------------------
-- 1. Establishment + restaurant (no brand: the menu prints "No Branch")
--    address / PIN / first coordinate pair are as printed on the menu footer
-- ---------------------------------------------------------------------
INSERT INTO establishment (establishment_id, name, normalized_name, address_line1, locality, postal_code, latitude, longitude)
SELECT 400070002, 'Sahara Hotel', 'sahara hotel', 'Near Kalpana Cinema, L.B.S Marg', 'Kurla (W.)', '400070',
       19.079669559569997, 72.88011808851121
WHERE NOT EXISTS (SELECT 1 FROM establishment WHERE establishment_id = 400070002);

-- has_bar / bar_license_type keep their defaults (FALSE / 'none'): no alcohol on the menu.
-- veg_nonveg_status is the roll-up of the loaded items (veg and non-veg dishes both present).
INSERT INTO restaurant (restaurant_id, establishment_id, display_name, normalized_name, veg_nonveg_status)
SELECT 400070002, 400070002, 'Sahara Hotel', 'sahara hotel', 'veg_and_nonveg'
WHERE NOT EXISTS (SELECT 1 FROM restaurant WHERE restaurant_id = 400070002);

-- ---------------------------------------------------------------------
