INSERT INTO restaurant_service_mode (restaurant_id, service_mode_id, is_active, notes) VALUES
(400070002, (SELECT service_mode_id FROM service_mode WHERE code = 'delivery'), TRUE, NULL),
(400070002, (SELECT service_mode_id FROM service_mode WHERE code = 'bulk_catering'), TRUE, 'Party Orders Should Be Confirmed One Day Before');

-- ---------------------------------------------------------------------
-- 4. Delivery capability. Only the providers are printed: no radius, minimum order or charge.
