-- ---------------------------------------------------------------------
INSERT INTO restaurant_delivery (restaurant_id, delivery_available) VALUES (400070002, TRUE);

INSERT INTO restaurant_delivery_provider (restaurant_delivery_provider_id, restaurant_id, delivery_provider_id, is_available, delivery_charge_type_code, effective_from) VALUES
(400070002001, 400070002, (SELECT delivery_provider_id FROM delivery_provider WHERE provider_code = 'SWIGGY'), TRUE, 'fixed', (clock_timestamp() AT TIME ZONE 'UTC')),
