INSERT INTO canonical_dish_name (canonical_dish_name_id, canonical_dish_id, language_code, name, normalized_name, name_type_code)
SELECT v.id, v.dish_id, 'en', v.nm, v.nn, 'primary' FROM v
WHERE EXISTS (SELECT 1 FROM canonical_dish c WHERE c.canonical_dish_id = v.dish_id AND c.normalized_name = v.nn);

