-- ---------------------------------------------------------------------
-- 18. POST-LOAD CHECK (raises -> whole transaction rolls back)
-- ---------------------------------------------------------------------
DO $post$
DECLARE
    n_cat bigint; n_item bigint; n_var bigint; n_price bigint;
    n_bc bigint; n_bi bigint; n_tag bigint; n_av bigint;
BEGIN
    SELECT count(*) INTO n_cat FROM menu_category WHERE restaurant_id = 400070002;
    SELECT count(*) INTO n_item FROM menu_item WHERE restaurant_id = 400070002;
    SELECT count(*) INTO n_var FROM menu_item_variant v
      JOIN menu_item i ON i.menu_item_id = v.menu_item_id WHERE i.restaurant_id = 400070002;
    SELECT count(*) INTO n_price FROM menu_item_price p
      JOIN menu_item_variant v ON v.variant_id = p.variant_id
      JOIN menu_item i ON i.menu_item_id = v.menu_item_id WHERE i.restaurant_id = 400070002;
    SELECT count(*) INTO n_bc FROM menu_board_category WHERE restaurant_id = 400070002;
    SELECT count(*) INTO n_bi FROM menu_board_item WHERE restaurant_id = 400070002;
    SELECT count(*) INTO n_tag FROM menu_item_tag t
      JOIN menu_item i ON i.menu_item_id = t.menu_item_id WHERE i.restaurant_id = 400070002;
    SELECT count(*) INTO n_av FROM menu_item_availability a
      JOIN menu_item i ON i.menu_item_id = a.menu_item_id WHERE i.restaurant_id = 400070002;

    IF n_cat <> 38 OR n_item <> 498 OR n_var <> 551 OR n_price <> 551
       OR n_bc <> 38 OR n_bi <> 498 OR n_tag <> 65 OR n_av <> 10 THEN
        RAISE EXCEPTION 'Sahara Hotel post-load check failed: categories=%, items=%, variants=%, prices=%, board_categories=%, board_items=%, tags=%, availability=%',
            n_cat, n_item, n_var, n_price, n_bc, n_bi, n_tag, n_av;
    END IF;

    IF EXISTS (SELECT 1 FROM menu_item i
                WHERE i.restaurant_id = 400070002
                  AND NOT EXISTS (SELECT 1 FROM menu_item_variant v WHERE v.menu_item_id = i.menu_item_id)) THEN
        RAISE EXCEPTION 'Sahara Hotel post-load check failed: a menu_item has no variant';
    END IF;

    RAISE NOTICE 'Sahara Hotel loaded: % categories, % items, % variants, % prices', n_cat, n_item, n_var, n_price;
END
$post$;

COMMIT;

